def _read_json_file(path: str) -> dict:
    # V9: PostgreSQL is checked first for JSON/settings; local file is fallback.
    try:
        obj_db = _spina_pg_read_json(path)
        if isinstance(obj_db, dict):
            return obj_db
    except Exception:
        pass
    try:
        import json
        with open(path, "r", encoding="utf-8") as f:
            obj = json.load(f)
        return obj if isinstance(obj, dict) else {}
    except Exception:
        return {}

def _write_json_atomic(path: str, data: dict) -> bool:
    # V9: write JSON/settings to PostgreSQL first, then keep a local safety mirror.
    db_ok = False
    try:
        db_ok = bool(_spina_pg_write_json(path, data))
    except Exception:
        db_ok = False
    local_ok = False
    try:
        import json
        d = os.path.dirname(path) or "."
        try:
            os.makedirs(d, exist_ok=True)
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0001', 'suppressed exception excpass_0001', __spina_exc)
            pass
        tmp = path + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(data, f, ensure_ascii=False, indent=2)
        os.replace(tmp, path)
        local_ok = True
    except Exception:
        local_ok = False
    return bool(db_ok or local_ok)

def load_settings() -> dict:
    # Backwards compatible: ignore any legacy keys found in older settings files.
    s = dict(_DEFAULT_SETTINGS)
    s.update(_read_json_file(SETTINGS_FILE) or {})

    # UI theme (light/dark)
    try:
        t = str(s.get("ui_theme") or _DEFAULT_SETTINGS.get("ui_theme", "dark")).strip().lower()
    except Exception:
        t = str(_DEFAULT_SETTINGS.get("ui_theme", "dark")).strip().lower()
    if t not in ("dark", "light"):
        t = "dark" if t.startswith("d") else "light"
    s["ui_theme"] = t

    # Optional custom reports root
    try:
        rr = str(s.get("reports_root") or "").strip()
    except Exception:
        rr = ""
    s["reports_root"] = rr

    # Auto Daily Close: close Data Bank dates after N days. 0 disables it.
    try:
        acd = int(float(str(s.get("auto_close_after_days", 0) or 0).strip()))
    except Exception:
        acd = 0
    if acd < 0:
        acd = 0
    if acd > 365:
        acd = 365
    s["auto_close_after_days"] = acd

    return s

def save_settings(s: dict) -> bool:
    # Persist only known keys
    out = {}
    for k in _DEFAULT_SETTINGS.keys():
        if k in s:
            out[k] = s[k]
    return _write_json_atomic(SETTINGS_FILE, out)

