_LOG_FILE = _init_logger()

def _log_exc(context: str, exc: Exception | None = None):
    """Log exceptions to data/spina_app.log (best-effort)."""
    try:
        if exc is None:
            _logging.exception(context)
        else:
            _logging.error(
                "%s: %s",
                context,
                exc,
                exc_info=(type(exc), exc, exc.__traceback__),
            )
    except Exception:
        try:
            print(f"[SPINA][ERROR] {context}: {exc}", file=sys.stderr)
        except Exception:
            return


# --- BEGIN: log suppressed exceptions (log-once) ---
try:
    _SUPPRESS_LOG_ONCE_KEYS
except NameError:
    _SUPPRESS_LOG_ONCE_KEYS = set()

def _log_suppressed_once(key: str, context: str, exc: Exception | None = None):
    """Log a suppressed exception only once per key (to avoid log spam)."""
    try:
        k = str(key or context or "suppressed")
        if k in _SUPPRESS_LOG_ONCE_KEYS:
            return
        _SUPPRESS_LOG_ONCE_KEYS.add(k)
    except Exception:
        # Never call this function recursively from its own failure path.
        k = str(context or "suppressed")
    try:
        _log_exc(context, exc)
    except Exception:
        try:
            print(f"[SPINA][SUPPRESSED] {context}: {exc}", file=sys.stderr)
        except Exception:
            return
# --- END: log suppressed exceptions (log-once) ---

