def _is_advance_on(db, name: str, day_yyyy_mm_dd: str, loan_type: str = "Regular") -> bool:
    """Return True if any transaction for `name` has an [ADV:s..e] tag that covers day_yyyy_mm_dd.
    Falls back quietly to False if anything goes wrong.
    """
    try:
        lt = loan_type
        # Normalize if the DB helper provides it
        if hasattr(db, "_effective_lt"):
            lt = db._effective_lt(loan_type)
        cur = db.conn.cursor()
        uid = None
        try:
            if hasattr(db, 'get_client_uid'):
                uid = db.get_client_uid(name, loan_type=lt)
        except Exception:
            uid = None
        if uid:
            cur.execute(
                """
                SELECT description
                FROM transactions
                WHERE ((client_uid = ?) OR ((client_uid IS NULL OR TRIM(client_uid)='') AND name = ?))
                  AND IFNULL(NULLIF(TRIM(loan_type),''),'Regular') = IFNULL(NULLIF(TRIM(?),''),'Regular')
                  AND description LIKE '%ADV%'
                """,
                (uid, name, lt),
            )
        else:
            cur.execute(
                """
                SELECT description
                FROM transactions
                WHERE name = ?
                  AND loan_type = ?
                  AND description LIKE '%ADV%'
                """,
                (name, lt),
            )
        rows = cur.fetchall() or []
        for (desc,) in rows:
            for s, e in (parse_advance_ranges(desc or "") or []):
                if s and e and s <= day_yyyy_mm_dd <= e:
                    return True
    except Exception as __spina_exc:
        _log_suppressed_once('excpass_0164', 'suppressed exception excpass_0164', __spina_exc)
        pass
    return False

def _adv_paid_on_dates_covering(db, name: str, day_yyyy_mm_dd: str, loan_type: str = "Regular"):
    """Return sorted list of *payment dates* (YYYY-MM-DD) whose ADV tag covers `day_yyyy_mm_dd`.

    Rules:
      - We only look at transactions whose description contains an [ADV:...] tag.
      - We EXCLUDE the payment date itself (so ADV is shown only on the covered days, not on the payment day).
      - If multiple ADV payments cover the same day, we return all unique payment dates.
    """
    try:
        lt = loan_type
        if hasattr(db, "_effective_lt"):
            lt = db._effective_lt(loan_type)

        cur = db.conn.cursor()
        uid = None
        try:
            if hasattr(db, 'get_client_uid'):
                uid = db.get_client_uid(name, loan_type=lt)
        except Exception:
            uid = None
        if uid:
            cur.execute(
                """
                SELECT date, description
                FROM transactions
                WHERE ((client_uid = ?) OR ((client_uid IS NULL OR TRIM(client_uid)='') AND name = ?))
                  AND IFNULL(NULLIF(TRIM(loan_type),''),'Regular') = IFNULL(NULLIF(TRIM(?),''),'Regular')
                  AND description LIKE '%ADV%'
                """,
                (uid, name, lt),
            )
        else:
            cur.execute(
                """
                SELECT date, description
                FROM transactions
                WHERE name = ?
                  AND loan_type = ?
                  AND description LIKE '%ADV%'
                """,
                (name, lt),
            )
        rows = cur.fetchall() or []
        out = set()
        for tx_date, desc in rows:
            paid_on = (str(tx_date or "")[:10]).strip()
            if not paid_on:
                continue
            for s, e in (parse_advance_ranges(desc or "") or []):
                if s and e and s <= day_yyyy_mm_dd <= e:
                    if paid_on != day_yyyy_mm_dd:
                        out.add(paid_on)
        return sorted(out)
    except Exception:
        return []


def _spina_route_adv_marker_for(db, name: str, day_yyyy_mm_dd: str, loan_type: str = "Regular"):
    """Robust Collector Route ADV lookup for PostgreSQL test builds.

    Returns (True, adv_end_date) when an ADV range covers the ledger day.
    It is intentionally case-insensitive on name and supports client_uid fallback.
    The actual payment date is included when the ADV range covers it, so
    collector route can show both payment-day advance and future advance days.
    """
    try:
        day = str(day_yyyy_mm_dd or "")[:10]
        nm = str(name or "").strip()
        if not day or not nm:
            return (False, "")
        try:
            import re as _re_adv_route
            nm_clean = _re_adv_route.sub(r"\s*\((?:7x7|7×7|regular|reg)\)\s*$", "", nm, flags=_re_adv_route.IGNORECASE).strip() or nm
        except Exception:
            nm_clean = nm
        lt_raw = str(loan_type or "Regular")
        lt_key = "7x7" if ("7x7" in lt_raw.lower().replace(" ", "").replace("×", "x")) else "regular"

        cur = db.conn.cursor()
        uid = ""
        try:
            if hasattr(db, "get_client_uid"):
                uid = str(db.get_client_uid(nm_clean, loan_type=("7x7" if lt_key == "7x7" else "Regular")) or "").strip()
        except Exception:
            uid = ""

        # Use a normalized loan_type expression so legacy blanks still count as Regular.
        if uid:
            cur.execute(
                """
                SELECT date, description
                  FROM transactions
                 WHERE description IS NOT NULL
                   AND TRIM(description) <> ''
                   AND description ILIKE '%ADV%'
                   AND (client_uid = ? OR UPPER(TRIM(name)) = UPPER(TRIM(?)))
                   AND (CASE WHEN LOWER(REPLACE(REPLACE(COALESCE(loan_type,'Regular'),' ',''),'×','x')) LIKE '%7x7%' THEN '7x7' ELSE 'regular' END) = ?
                """,
                (uid, nm_clean, lt_key),
            )
        else:
            cur.execute(
                """
                SELECT date, description
                  FROM transactions
                 WHERE description IS NOT NULL
                   AND TRIM(description) <> ''
                   AND description ILIKE '%ADV%'
                   AND UPPER(TRIM(name)) = UPPER(TRIM(?))
                   AND (CASE WHEN LOWER(REPLACE(REPLACE(COALESCE(loan_type,'Regular'),' ',''),'×','x')) LIKE '%7x7%' THEN '7x7' ELSE 'regular' END) = ?
                """,
                (nm_clean, lt_key),
            )
        rows = cur.fetchall() or []
        best_end = ""
        for tx_date, desc in rows:
            # Collector route must show ADV even on the actual payment-entry date
            # when the payment has an ADV range covering today.
            paid_on = str(tx_date or "")[:10]
            for s, e in (parse_advance_ranges(desc or "") or []):
                ss = str(s or "")[:10]
                ee = str(e or "")[:10]
                if not ss or not ee:
                    continue
                if ee < ss:
                    ss, ee = ee, ss
                if ss <= day <= ee:
                    if (not best_end) or ee > best_end:
                        best_end = ee
        return (bool(best_end), best_end)
    except Exception as __spina_exc:
        try:
            _log_suppressed_once('route_adv_marker_lookup_failed', 'collector route ADV lookup failed', __spina_exc)
        except Exception:
            pass
        return (False, "")





from spina_app.utilities.formatting import fmt_currency






def _getv(obj, key, default=None):
    """Safe getter for dict / sqlite3.Row / objects."""
    try:
        # dict-like .get
        return obj.get(key, default)
    except Exception:
        try:
            return obj[key]
        except Exception:
            return default



def _sum_paid_per_day(rows):
    """Sum payments per date in a way that matches the app's Data Bank behavior.

    - Data Bank updates are keyed by (name, loan_type, date) so normally there's only 1 row per date.
    - If legacy/duplicate rows exist, we treat the **last non-zero** payment as the effective payment.
    - We do NOT let later 0.00 "reason-only" rows overwrite an existing non-zero payment.
    - We ignore ADV-only marker rows (0.00 with an ADV range tag) so they don't zero-out totals.

    Works for dicts and sqlite3.Row.
    """
    if not rows:
        return 0.0

    per_day = {}

    # acceptable aliases for keys
    date_keys = ('date','tx_date','trans_date','txdate','txDate','txdate_str')
    pay_keys  = ('payment','paid','amt','amount','pay')

    for r in rows:
        # find date string
        d = None
        for k in date_keys:
            d = _getv(r, k, None)
            if d:
                break
        if d is None:
            try:
                d = r['date']
            except Exception:
                d = None
        if d is None:
            continue

        # Normalize date strings (legacy rows may include time). Keep only YYYY-MM-DD.
        try:
            if isinstance(d, str):
                ds = d.strip()
                if len(ds) >= 10:
                    d = ds[:10]
                else:
                    d = ds
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0165', 'suppressed exception excpass_0165', __spina_exc)
            pass

        # get numeric payment
        p = 0.0
        found_payment = False
        for k in pay_keys:
            val = _getv(r, k, None)
            if val not in (None, ''):
                try:
                    p = float(val)
                except Exception:
                    p = 0.0
                found_payment = True
                break

        # description (for ADV marker detection)
        desc = ""
        try:
            desc = str(_getv(r, 'description', '') or '')
        except Exception:
            desc = ""

        # If this is an ADV-only marker row (0 payment + ADV tag/text), ignore it.
        try:
            if (abs(p) < 1e-9) and desc and _parse_any_adv_range(desc):
                # Only ignore when payment is 0; non-zero ADV rows are real payments.
                continue
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0166', 'suppressed exception excpass_0166', __spina_exc)
            pass

        # Keep last non-zero; do not overwrite non-zero with 0.
        if found_payment and abs(p) >= 1e-9:
            per_day[d] = p
        else:
            # Only set zero if we have nothing for that day yet.
            per_day.setdefault(d, 0.0)

    try:
        return round(sum(float(v or 0) for v in per_day.values()), 2)
    except Exception:
        try:
            return round(sum(per_day.values()), 2)
        except Exception:
            return 0.0

def _wrap_to_width(text, font, size, max_w):
    words = (text or "").split()
    lines, cur = [], ""
    for w in words:
        test = (cur + " " + w).strip()
        if not cur or stringWidth(test, font, size) <= max_w:
            cur = test
        else:
            lines.append(cur)
            cur = w
    if cur:
        lines.append(cur)
    return lines

def draw_notes_aligned(c, x_label, y, max_w, note_text,
                       font="Helvetica", size=9, leading=None, label="Note:"):
    """
    Draws:
        Note:  YYYY-MM-DD   wrapped note text
               (blank)      continuation lines aligned under text column
    Returns the new y after drawing.
    """
    if leading is None:
        leading = size + 2

    c.setFont(font, size)

    label_w = stringWidth(label, font, size)
    gap = 6  # space after label
    x_text = x_label + label_w + gap

    # Date column width fits '0000-00-00'
    date_col_w = stringWidth("0000-00-00", font, size) + 6
    text_col_w = max_w - (x_text - x_label) - date_col_w
    if text_col_w < 40:
        text_col_w = 40

    visual_lines = []
    for raw in (note_text or "").splitlines():
        raw = raw.strip()
        if not raw:
            continue
        if ":" in raw and raw[:10].count("-") == 2:
            date, rest = raw.split(":", 1)
            date, rest = date.strip(), rest.strip()
        else:
            date, rest = "", raw

        wrapped = _wrap_to_width(rest, font, size, text_col_w) or [""]
        for i, seg in enumerate(wrapped):
            visual_lines.append((date if i == 0 else "", seg))

    drew_label = False
    cur_y = y
    for date, seg in visual_lines:
        if not drew_label:
            c.drawString(x_label, cur_y, label)
            drew_label = True
        if date:
            c.drawString(x_text, cur_y, date)
        c.drawString(x_text + date_col_w, cur_y, seg)
        cur_y -= leading

    return cur_y
# --- end aligned Note ---




