    def _users_db_path(self) -> str:
        import os
        os.makedirs(DATA_DIR, exist_ok=True)
        return os.path.join(DATA_DIR, 'users.json')
    def _hash_password_legacy(self, password: str, salt: str) -> str:
        import hashlib
        s = (salt or '') + (password or '')
        try:
            return hashlib.sha256(s.encode('utf-8')).hexdigest()
        except Exception:
            return ''

    def _hash_password(self, password: str, salt: str, scheme: str = 'pbkdf2_sha256', iterations: int = 200000) -> str:
        """Hash passwords using PBKDF2-HMAC-SHA256 by default.

        Legacy scheme supported for backward compatibility:
          - scheme: 'sha256_salt' (or 'legacy') uses SHA-256(salt + password)

        Stored records should include:
          - scheme: 'pbkdf2_sha256' (recommended) or 'sha256_salt'
          - iterations: integer (PBKDF2 only)
        """
        import hashlib
        try:
            scheme = (scheme or 'pbkdf2_sha256').strip().lower()
        except Exception:
            scheme = 'pbkdf2_sha256'

        if scheme in ('sha256', 'sha256_salt', 'legacy'):
            return self._hash_password_legacy(password, salt)

        # PBKDF2-HMAC-SHA256 (default)
        try:
            iters = int(iterations or 200000)
            if iters < 100000:
                iters = 100000
        except Exception:
            iters = 200000

        try:
            dk = hashlib.pbkdf2_hmac(
                'sha256',
                (password or '').encode('utf-8'),
                (salt or '').encode('utf-8'),
                iters
            )
            return dk.hex()
        except Exception:
            return ''

    def _make_salt(self) -> str:

    
        try:
            import secrets
            return secrets.token_hex(16)
        except Exception:
            # fallback
            import random, string
            return ''.join(random.choice(string.hexdigits.lower()) for _ in range(32))

    def _default_password_for(self, username: str):
        u = (username or '').strip().lower()
        return {'admin': 'admin123', 'encoder': 'encoder123', 'viewer': 'viewer123', 'system': 'system123'}.get(u)

    def _is_default_password_rec(self, username: str, rec: dict) -> bool:
        """True if this user's stored hash matches the known default password."""
        try:
            pw = self._default_password_for(username)
            if not pw:
                return False
            salt = (rec or {}).get('salt') or ''
            h = (rec or {}).get('hash') or ''
            if not salt or not h:
                return False
            scheme = (rec or {}).get('scheme') or 'sha256_salt'
            iters = (rec or {}).get('iterations') or 200000
            import hmac
            return hmac.compare_digest(
                self._hash_password(pw, salt, scheme=scheme, iterations=iters),
                str(h),
            )
        except Exception:
            return False

    def _must_change_password(self, username: str, password_entered: str = '') -> bool:
        """Enforce password change if account is still using the known defaults."""
        try:
            db = self._load_users_db()
            users = db.get('users') or {}
            key = (username or '').strip()
            rec = users.get(key)
            if not isinstance(rec, dict):
                return False

            if bool(rec.get('must_change_password')):
                return True

            # Legacy installs: if user logs in using the default password, flag it.
            dflt = self._default_password_for(key)
            if dflt and (password_entered or '') == dflt and self._is_default_password_rec(key, rec):
                rec['must_change_password'] = True
                rec['created_from_default'] = True
                users[key] = rec
                db['users'] = users
                self._save_users_db(db)
                return True

            return False
        except Exception:
            return False

    def _set_user_password(self, username: str, new_password: str) -> bool:
        """Update password hash+salt for user and clear must_change_password."""
        try:
            from datetime import datetime
            db = self._load_users_db()
            users = db.get('users') or {}
            key = (username or '').strip()
            rec = users.get(key)
            if not isinstance(rec, dict):
                return False

            salt = self._make_salt()
            rec['salt'] = salt
            iters = 200000
            rec['scheme'] = 'pbkdf2_sha256'
            rec['iterations'] = iters
            rec['hash'] = self._hash_password(new_password or '', salt, scheme=rec['scheme'], iterations=iters)
            rec['must_change_password'] = False
            rec['pw_changed_at'] = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
            users[key] = rec
            db['users'] = users
            self._save_users_db(db)
            return True
        except Exception:
            _log_exc('set_user_password')
            _alert_user('Save Error', 'Failed to update password.\nSee log: data/spina_app.log', kind='warning')
            return False

    def _force_change_password_dialog(self, username: str, old_password: str = '') -> bool:
        """Modal dialog that forces a password change. Returns True if changed."""
        import tkinter as tk
        from tkinter import ttk

        result = {'ok': False}

        dlg = tk.Toplevel(self.root)
        dlg.title('Change Password')
        try:
            dlg.transient(self.root)
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0172', 'suppressed exception excpass_0172', __spina_exc)
            pass
        dlg.resizable(False, False)

        outer = ttk.Frame(dlg, padding=16)
        outer.pack(fill='both', expand=True)

        ttk.Label(outer, text='Password Change Required', font=('TkDefaultFont', 11, 'bold')).grid(row=0, column=0, sticky='w')
        ttk.Label(
            outer,
            text=f"User '{username}' is using the default password.\nYou must set a new password to continue.",
            justify='left'
        ).grid(row=1, column=0, sticky='w', pady=(6, 12))

        new_var = tk.StringVar(value='')
        conf_var = tk.StringVar(value='')
        msg_var = tk.StringVar(value='')

        ttk.Label(outer, text='New password').grid(row=2, column=0, sticky='w')
        new_ent = ttk.Entry(outer, textvariable=new_var, show='*', width=28)
        new_ent.grid(row=3, column=0, sticky='w')

        ttk.Label(outer, text='Confirm password').grid(row=4, column=0, sticky='w', pady=(10, 0))
        conf_ent = ttk.Entry(outer, textvariable=conf_var, show='*', width=28)
        conf_ent.grid(row=5, column=0, sticky='w')

        msg = ttk.Label(outer, textvariable=msg_var, foreground='#b00020')
        msg.grid(row=6, column=0, sticky='w', pady=(8, 0))

        btns = ttk.Frame(outer)
        btns.grid(row=7, column=0, sticky='e', pady=(14, 0))

        def _save():
            new_pw = (new_var.get() or '')
            conf_pw = (conf_var.get() or '')
            dflt = self._default_password_for(username) or ''

            if len(new_pw) < 8:
                msg_var.set('Password must be at least 8 characters.')
                return
            if new_pw != conf_pw:
                msg_var.set('Passwords do not match.')
                return
            if old_password and new_pw == old_password:
                msg_var.set('New password must be different from the old password.')
                return
            if dflt and new_pw == dflt:
                msg_var.set('New password cannot be the default password.')
                return

            if not self._set_user_password(username, new_pw):
                msg_var.set('Failed to save new password. Check log.')
                return

            result['ok'] = True
            try:
                dlg.grab_release()
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0173', 'suppressed exception excpass_0173', __spina_exc)
                pass
            dlg.destroy()

        def _cancel():
            # Do not allow bypass when change is required.
            result['ok'] = False
            try:
                dlg.grab_release()
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0174', 'suppressed exception excpass_0174', __spina_exc)
                pass
            dlg.destroy()

        ttk.Button(btns, text='Save Password', command=_save).pack(side='right')
        ttk.Button(btns, text='Cancel', command=_cancel).pack(side='right', padx=(0, 8))

        def _on_enter(_e=None):
            _save()

        try:
            new_ent.bind('<Return>', _on_enter)
            conf_ent.bind('<Return>', _on_enter)
        except Exception as e:
            _log_ignored("ui.bind failed", e, key="ui.bind_failed")

        try:
            dlg.grab_set()
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0175', 'suppressed exception excpass_0175', __spina_exc)
            pass
        try:
            new_ent.focus_set()
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0176', 'suppressed exception excpass_0176', __spina_exc)
            pass

        # Center dialog on parent
        try:
            dlg.update_idletasks()
            x = self.root.winfo_rootx() + (self.root.winfo_width() // 2) - (dlg.winfo_width() // 2)
            y = self.root.winfo_rooty() + (self.root.winfo_height() // 2) - (dlg.winfo_height() // 2)
            dlg.geometry(f"+{max(x, 0)}+{max(y, 0)}")
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0177', 'suppressed exception excpass_0177', __spina_exc)
            pass

        self.root.wait_window(dlg)
        return bool(result.get('ok'))

    def _save_users_db(self, data: dict) -> None:
        import os, json
        p = self._users_db_path()
        try:
            os.makedirs(os.path.dirname(p), exist_ok=True)
        except Exception:
            _log_exc('save_users_db:makedirs')
        try:
            tmp = p + '.tmp'
            with open(tmp, 'w', encoding='utf-8') as f:
                json.dump(data, f, ensure_ascii=False, indent=2)
            os.replace(tmp, p)
            # Best-effort: restrict permissions on Unix-like systems
            try:
                if os.name != 'nt':
                    os.chmod(p, 0o600)
            except Exception:
                _log_exc('save_users_db:chmod')

        except Exception:
            _log_exc('save_users_db:write')
            _alert_user('Save Error', 'Failed to save user accounts (data/users.json).\n\nCheck permissions/disk space.\nSee log: data/spina_app.log', kind='warning')

    def _load_users_db(self) -> dict:
        """Load users database from data/users.json. If missing, create defaults.

        Default accounts (created only if missing):
          - admin / admin123   -> Admin
          - encoder / encoder123 -> Encoder
          - viewer / viewer123 -> Viewer
          - system / system123 -> System
        """
        import os, json
        p = self._users_db_path()
        data = {}
        try:
            with open(p, 'r', encoding='utf-8') as f:
                data = json.load(f) or {}
        except Exception:
            data = {}

        users = data.get('users')
        if not isinstance(users, dict):
            users = {}

        changed = False
        defaults = {
            'admin':  ('Admin',  'admin123'),
            'encoder':('Encoder','encoder123'),
            'viewer': ('Viewer', 'viewer123'),
            'system': ('System', 'system123'),
        }

        for uname, (role, pw) in defaults.items():
            rec = users.get(uname)
            if not isinstance(rec, dict) or not rec.get('salt') or not rec.get('hash'):
                salt = self._make_salt()
                users[uname] = {
                    'role': role,
                    'salt': salt,
                    'scheme': 'pbkdf2_sha256',
                    'iterations': 200000,
                    'hash': self._hash_password(pw, salt, scheme='pbkdf2_sha256', iterations=200000),
                    'must_change_password': True,
                    'created_from_default': True,
                    'pw_changed_at': None,
                }
                changed = True
            else:
                # normalize role to known values
                r = (rec.get('role') or '').strip()
                if r not in ('Admin', 'Encoder', 'Viewer', 'System'):
                    rec['role'] = role
                    users[uname] = rec
                    changed = True

                # Legacy-only check. Modern records already store this flag, so do
                # not run an expensive PBKDF2 hash for every account on every read.
                if 'must_change_password' not in rec:
                    try:
                        rec['must_change_password'] = bool(self._is_default_password_rec(uname, rec))
                        if rec['must_change_password']:
                            rec['created_from_default'] = True
                        users[uname] = rec
                        changed = True
                    except Exception as __spina_exc:
                        _log_suppressed_once('excpass_0178', 'suppressed exception excpass_0178', __spina_exc)

        data['version'] = int(data.get('version') or 1)
        data['users'] = users

        if changed or (not os.path.exists(p)):
            self._save_users_db(data)
        return data

    def _verify_login(self, username: str, password: str):
        try:
            db = self._load_users_db()
            users = db.get('users') or {}
            rec = users.get((username or '').strip())
            if not isinstance(rec, dict):
                return None
            salt = rec.get('salt') or ''
            h = rec.get('hash') or ''
            if not salt or not h:
                return None
            scheme = (rec.get('scheme') or 'sha256_salt')
            iters = rec.get('iterations') or 200000
            import hmac
            if not hmac.compare_digest(
                self._hash_password(password or '', salt, scheme=scheme, iterations=iters),
                str(h),
            ):
                return None

            # Transparent upgrade: re-hash legacy SHA-256 salted passwords to PBKDF2 on successful login
            try:
                if (scheme or '').strip().lower() in ('sha256', 'sha256_salt', 'legacy'):
                    new_salt = self._make_salt()
                    rec['salt'] = new_salt
                    rec['scheme'] = 'pbkdf2_sha256'
                    rec['iterations'] = 200000
                    rec['hash'] = self._hash_password(password or '', new_salt, scheme='pbkdf2_sha256', iterations=200000)
                    users[(username or '').strip()] = rec
                    db['users'] = users
                    self._save_users_db(db)
            except Exception:
                _log_exc('upgrade_password_hash')

            role = (rec.get('role') or '').strip() or 'Viewer'
            if role not in ('Admin', 'Encoder', 'Viewer', 'System'):
                role = 'Viewer'
            return role
        except Exception:
            return None

    def _load_last_user(self) -> str:
        import json
        try:
            with open(self._access_prefs_path(), 'r', encoding='utf-8') as f:
                obj = json.load(f) or {}
            return (obj.get('user') or '').strip()
        except Exception:
            return ''

    def _save_last_user(self, user: str) -> None:

        import json

        try:

            p = self._access_prefs_path()

            obj = {}

            try:

                with open(p, 'r', encoding='utf-8') as f:

                    obj = json.load(f) or {}

            except Exception:

                obj = {}

            obj['user'] = (user or '').strip()

            if not _write_json_atomic(p, obj):

                raise IOError("atomic write failed")

        except Exception as __spina_exc:

            _log_suppressed_once("save_last_user", "save_last_user failed", __spina_exc)

    def _prompt_login(self, default_user: str = 'admin'):
        """Login dialog: returns (username, role) or (None, None) if cancelled."""
        import tkinter as tk
        from tkinter import ttk

        # Ensure users DB exists and load users
        db = self._load_users_db()
        users = db.get('users') or {}
        user_list = sorted([u for u in users.keys() if isinstance(u, str) and u.strip()], key=lambda s: s.lower())

        if not user_list:
            user_list = ['admin']
