        hint = ttk.Label(outer, text='(Default accounts are created if missing: admin/admin123, encoder/encoder123, viewer/viewer123, system/system123. Default passwords must be changed on first login.)', wraplength=360, foreground='#555555')
        hint.grid(row=5, column=0, sticky='w', pady=(8, 0))

        btns = ttk.Frame(outer)
        btns.grid(row=6, column=0, sticky='e', pady=(14, 0))

        def _ok():
            u = (user_var.get() or '').strip()
            p = (pw_var.get() or '')
            role = self._verify_login(u, p)
            if not role:
                msg_var.set('Invalid username or password.')
                try:
                    ent.focus_set()
                    ent.selection_range(0, 'end')
                except Exception as __spina_exc:
                    _log_suppressed_once('excpass_0180', 'suppressed exception excpass_0180', __spina_exc)
                    pass
                return

            # Enforce password change if account is still using a known default password
            try:
                if self._must_change_password(u, p):
                    if not self._force_change_password_dialog(u, old_password=p):
                        msg_var.set('Password change required to continue.')
                        return
            except Exception:
                _log_exc('force_change_password')
                msg_var.set('Password change required, but change dialog failed. See log.')
                return

            result['user'] = u
            result['role'] = role
            try:
                dlg.grab_release()
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0181', 'suppressed exception excpass_0181', __spina_exc)
                pass
            dlg.destroy()

        def _cancel():
            try:
                dlg.grab_release()
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0182', 'suppressed exception excpass_0182', __spina_exc)
                pass
            dlg.destroy()

        ttk.Button(btns, text='Login', command=_ok).pack(side='right')
        ttk.Button(btns, text='Cancel', command=_cancel).pack(side='right', padx=(0, 8))

        def _on_enter(_e=None):
            _ok()

        try:
            ent.bind('<Return>', _on_enter)
            cb.bind('<Return>', _on_enter)
        except Exception as e:
            _log_ignored("ui.bind failed", e, key="ui.bind_failed")

        try:
            dlg.grab_set()
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0183', 'suppressed exception excpass_0183', __spina_exc)
            pass
        try:
            ent.focus_set()
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0184', 'suppressed exception excpass_0184', __spina_exc)
            pass

        # Center dialog on parent
        try:
            dlg.update_idletasks()
            x = self.root.winfo_rootx() + (self.root.winfo_width() // 2) - (dlg.winfo_width() // 2)
            y = self.root.winfo_rooty() + (self.root.winfo_height() // 2) - (dlg.winfo_height() // 2)
            dlg.geometry(f"+{max(x, 0)}+{max(y, 0)}")
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0185', 'suppressed exception excpass_0185', __spina_exc)
            pass

        self.root.wait_window(dlg)
        return (result.get('user'), result.get('role'))


