    def apply_role_access(self):
        """Apply role-based UI restrictions."""
        role = (getattr(self, 'user_role', None) or 'Admin').strip()
        if role not in ('Admin', 'Encoder', 'Viewer', 'System'):
            role = 'Admin'

        if role != 'System':
            try:
                self._hide_system_data_tab()
            except Exception:
                pass

        try:
            if role == 'System':
                self._show_audit_tab()
            else:
                self._hide_audit_tab()
        except Exception:
            pass

        # Clear overlays (if any)
        try:
            self._remove_role_overlays()
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0195', 'suppressed exception excpass_0195', __spina_exc)
            pass

        # Restore the normal working tabs before applying role-specific hides.
        try:
            self._restore_main_tabs()
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_restore_tabs_before_role', 'suppressed exception excpass_restore_tabs_before_role', __spina_exc)
            pass

        if role == 'Admin':
            # Full access
            try:
                self.nb.select(self.tab_data)
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0196', 'suppressed exception excpass_0196', __spina_exc)
                pass
            return

        if role == 'Viewer':
            # Reports tab only
            try:
                self.nb.hide(self.tab_data)
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0197', 'suppressed exception excpass_0197', __spina_exc)
                pass
            try:
                self.nb.hide(self.tab_clients)
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0198', 'suppressed exception excpass_0198', __spina_exc)
                pass
            try:
                self.nb.hide(self.tab_collectors)
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0199', 'suppressed exception excpass_0199', __spina_exc)
                pass
            try:
                self.nb.select(self.tab_reports)
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0200', 'suppressed exception excpass_0200', __spina_exc)
                pass
            return

        if role == 'Encoder':
            # No Clients editing
            try:
                self.nb.hide(self.tab_clients)
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0201', 'suppressed exception excpass_0201', __spina_exc)
                pass

            # Import-only overlays for the allowed tabs
            try:
                self._role_overlay_data = self._make_import_only_overlay(
                    self.tab_data,
                    'Encoder Mode — Data Bank (Import Only)',
                    self._import_from_excel_entry,
                )
            except Exception:
                self._role_overlay_data = None

            # Encoder has full access to Reports tab (no overlay)
            self._role_overlay_reports = None

            # Encoder has full access to Collector's Route tab (no overlay)
            self._role_overlay_collectors = None

            try:
                self.nb.select(self.tab_reports)
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0202', 'suppressed exception excpass_0202', __spina_exc)
                pass
            return

        if role == 'System':
            # Give System the same Data Bank tab access used by Admin,
            # while still hiding the other non-system work areas.
            try:
                self.nb.hide(self.tab_clients)
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_system_0201', 'suppressed exception excpass_system_0201', __spina_exc)
                pass
            try:
                self.nb.hide(self.tab_reports)
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_system_0202', 'suppressed exception excpass_system_0202', __spina_exc)
                pass
            try:
                self.nb.hide(self.tab_collectors)
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_system_0203', 'suppressed exception excpass_system_0203', __spina_exc)
                pass

            # Hide the custom System-only helper tab and use the real admin Data Bank tab instead.
            try:
                self._hide_system_data_tab()
            except Exception:
                pass

            # No overlay: System should be able to work directly in the Data Bank tab.
            self._role_overlay_data = None
            self._role_overlay_reports = None
            self._role_overlay_collectors = None

            try:
                self.nb.select(self.tab_audit)
            except Exception:
                try:
                    self.nb.select(self.tab_data)
                except Exception as __spina_exc:
                    _log_suppressed_once('excpass_system_0204', 'suppressed exception excpass_system_0204', __spina_exc)
                    pass
            return

    def _is_client_new(self, name, ledger_date, days=None):






        """Return True if client is NEW.

        Rules:
        - If 'new_until' is explicitly set in the DB:
            * If it's an empty string or unparsable -> treat as explicit OFF (return False).
            * If it's a valid date -> return (ledger_date <= new_until). No fallback.
        - Otherwise (no explicit 'new_until' value present):
            * If 'days' is None/blank, default to prefs 'new_highlight_days' (default 7).
            * If 'days' > 0, return (ledger_date <= (created_at or date_released) + days).
            * Else False.
        """
        nm = (name or "").strip()
        if not nm:
            return False

        lt = self._mode_filter()

        try:
            from datetime import datetime, timedelta, date as _date
        except Exception:
            return False

        # Parse ledger date (fallback to today on error)
        try:
            ld = datetime.strptime(str(ledger_date), "%Y-%m-%d").date()
        except Exception:
            ld = _date.today()

        # Get DB conn
        try:
            conn = getattr(self, "conn", None) or getattr(getattr(self, "db", None), "conn", None)
        except Exception:
            conn = None
        if conn is None:
            return False

        # Load row
        try:
            cur = conn.cursor()
            row = cur.execute(
                "SELECT new_until, created_at, date_released FROM clients WHERE name=? AND loan_type=?",
                (nm, lt)
            ).fetchone()
        except Exception:
            row = None
        if not row:
            return False

        # --- Explicit override via new_until ---
        nu_raw = None
        try:
            nu_raw = row["new_until"]
        except Exception:
            try:
                nu_raw = row[0]
            except Exception:
                nu_raw = None

        if nu_raw is not None:
            s = str(nu_raw).strip()
            if not s:
                # Explicit OFF
                return False
            # Try to parse; if bad -> treat as OFF
            try:
                nu = datetime.strptime(s[:10], "%Y-%m-%d").date()
                return ld <= nu
            except Exception:
                return False

        # --- Fallback: created_at/date_released + days ---
        if days is None or (isinstance(days, str) and not str(days).strip()):
            try:
                days = _load_ledger_prefs().get('new_highlight_days', 7)
            except Exception:
                days = 7

        try:
            d_int = int(days or 0)
        except Exception:
            d_int = 0
        if d_int <= 0:
            return False

        # Use created_at else date_released
        ca_raw = None
        dr_raw = None
        try:
            ca_raw = row["created_at"]
        except Exception:
            try:
                ca_raw = row[1]
            except Exception:
                ca_raw = None
        try:
            dr_raw = row["date_released"]
        except Exception:
            try:
                dr_raw = row[2]
            except Exception:
                 dr_raw = None

        start_date = None
        for cand in (ca_raw, dr_raw):
            if cand:
                try:
                    start_date = datetime.strptime(str(cand)[:10], "%Y-%m-%d").date()
                    break
                except Exception:
                    continue
        if not start_date:
            return False

        try:
            return ld <= (start_date + timedelta(days=d_int))
        except Exception:
            return False



