    def _tk_button_hover(self, widget, normal_bg=None, hover_bg=None):
        """Small hover helper for plain tk buttons/labels."""
        try:
            if normal_bg is None:
                normal_bg = widget.cget('bg')
            if hover_bg is None:
                hover_bg = normal_bg
            widget.bind('<Enter>', lambda e, w=widget, h=hover_bg: w.configure(bg=h), add='+')
            widget.bind('<Leave>', lambda e, w=widget, n=normal_bg: w.configure(bg=n), add='+')
        except Exception as __spina_exc:
            _log_suppressed_once('modern_ui_pass_16103', 'modern UI button hover binding skipped', __spina_exc)
            pass


    def _set_mode(self, mode):
        """Fast switch between Regular and 7x7 from the modern segmented control."""
        try:
            mode = '7x7' if str(mode or '').lower().replace(' ', '') in ('7x7', '7×7') else 'Regular'
            if getattr(self, 'mode_var', None) is not None:
                if (self.mode_var.get() or '') == mode:
                    self._refresh_mode_toggle()
                    return
                self.mode_var.set(mode)
        except Exception:
            pass
        try:
            self._refresh_mode_toggle()
        except Exception as __spina_exc:
            _log_suppressed_once('modern_ui_pass_16147', 'modern UI mode toggle refresh skipped', __spina_exc)
            pass
        try:
            self._on_mode_change()
        except Exception as e:
            try:
                _log_suppressed_once('modern_mode_switch', 'modern mode switch failed', e)
            except Exception:
                pass




