    def switch_account(self):
        old_user = getattr(self, 'user_name', '') or ''
        old_role = getattr(self, 'user_role', '') or ''
        try:
            u, r = self._prompt_login(default_user=(self.user_name or 'admin'))
        except Exception as e:
            _log_exc('switch_account_login', e)
            messagebox.showerror('Switch Account', 'Failed to open the login dialog. See log for details.')
            return

        if not u or not r:
            return

        self.user_name = u
        self.user_role = r

        try:
            self._save_last_user(self.user_name)
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_switch_account_save_user', 'suppressed exception excpass_switch_account_save_user', __spina_exc)
            pass
        try:
            self._save_user_role(self.user_role)
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_switch_account_save_role', 'suppressed exception excpass_switch_account_save_role', __spina_exc)
            pass

        try:
            self._refresh_user_header()
        except Exception:
            pass
        try:
            self._rebuild_side_nav()
        except Exception:
            pass

        try:
            self.apply_role_access()
        except Exception as e:
            _log_exc('switch_account_apply_role_access', e)
            messagebox.showwarning('Switch Account', 'The account was switched, but the role UI could not be fully refreshed. Please restart the app if something looks wrong.')

        try:
            self.status_var.set(f'Switched account: {old_user} ({old_role}) -> {self.user_name} ({self.user_role})')
        except Exception:
            pass


