def _build_collectors_tab(self):
    """Collector's Route UI (organized + obvious selection + inline edit).

    Adds:
    - Obvious selection column (radio in single-select, checkbox in multi-select)
    - Per-row Actions column (View / Edit / Delete)
    - Multi-select bulk bar (Delete / Export / Clear)
    - Inline edit in the right-side panel (name + areas order + notes)
    """
    frm = self.tab_collectors

    # --- Header (title + search) ---
    header = ttk.Frame(frm)
