            try:
                _collector_name = getattr(self, "_ledger_forced_collector_name", "") or ""
            except Exception:
                _collector_name = ""

            if not _collector_name:
                # --- Clients tab header ---
                c.setFont(_PDF_FONT_BOLD, 16)
