    def _attempt_attach_on_run():
        try:
            g = globals()
            if 'app' in g and hasattr(g['app'], '__class__') and g['app'].__class__.__name__ in ('App', 'MainApp'):
                attach_direct_integration(g['app'])
                return
            if 'main' in g and callable(g['main']) and 'App' in g and hasattr(g['App'], '__init__'):
                orig_main = g['main']
                AppClass = g['App']
                g['main'] = wrapped_main
        except Exception:
            traceback.print_exc()
    
