    def _wrap_text_to_width(text, max_w, font_name=_PDF_FONT_BASE, font_size=9.5):
        s = (text or "").strip()
        if not s:
            return [""]
        words, lines, cur = s.split(), [], ""
        def _fits(t): return stringWidth(t, font_name, font_size) <= max_w
        for w in words:
            trial = (cur + " " + w).strip()
            if _fits(trial):
                cur = trial
            else:
                if cur:
                    lines.append(cur)
                if not _fits(w):
                    acc = ""
                    for ch in w:
                        if _fits(acc + ch):
                            acc += ch
                        else:
                            if acc:
                                lines.append(acc)
                            acc = ch
                    cur = acc
                else:
                    cur = w
        if cur:
            lines.append(cur)
        return lines

