        self.cashctl_avg_collection_var = tk.StringVar(value='Average Daily Collection: PHP 0.00')
        self.cashctl_future_cash_var = tk.StringVar(value='Average Forecast Collection: PHP 0.00')
        self.cashctl_current_available_var = tk.StringVar(value='Current Available Cash: PHP 0.00')
