from spina_app.utilities.text import _spina_crc_norm_text


def _spina_crc_norm_lt(_v):
    try:
        s = str(_v or "Regular").strip().lower().replace(" ", "").replace("×", "x")
    except Exception:
        s = "regular"
    return "7x7" if ("7x7" in s) else "Regular"


from spina_app.utilities.formatting import _spina_crc_fmt_money


def _spina_crc_clean_reason(_v):
    try:
        s = str(_v or "").strip()
    except Exception:
        s = ""
    if not s:
        return ""
    try:
        s = re.sub(r"\[RC:[^\]]+\]", "", s, flags=re.I).strip()
        s = re.sub(r"\[ADV:[^\]]+\]", "", s, flags=re.I).strip()
        s = re.sub(r"\s+", " ", s).strip()
    except Exception:
        pass
    return s


def _spina_crc_load_collectors():
    """Load collector route definitions from data/collectors.json in any supported schema."""
    path = ""
    try:
        path = data_path("collectors.json")
    except Exception:
        try:
            path = os.path.join(DATA_DIR, "collectors.json")
        except Exception:
            path = "collectors.json"
    try:
        with open(path, "r", encoding="utf-8") as f:
            raw = json.load(f)
    except Exception:
        raw = {}
    out = []
    try:
        if isinstance(raw, dict):
            for nm, rec in raw.items():
                areas = []
                notes = ""
                if isinstance(rec, dict):
                    areas = rec.get("areas") or rec.get("route") or []
                    notes = rec.get("notes") or ""
                elif isinstance(rec, list):
                    areas = rec
                areas = [str(a).strip() for a in (areas or []) if str(a).strip()]
                if str(nm or "").strip():
                    out.append({"name": str(nm).strip(), "areas": areas, "notes": str(notes or "")})
        elif isinstance(raw, list):
            for rec in raw:
                if isinstance(rec, dict):
                    nm = rec.get("name") or rec.get("collector") or rec.get("id") or ""
                    areas = rec.get("areas") or rec.get("route") or []
                    notes = rec.get("notes") or ""
                    areas = [str(a).strip() for a in (areas or []) if str(a).strip()]
                    if str(nm or "").strip():
                        out.append({"name": str(nm).strip(), "areas": areas, "notes": str(notes or "")})
                elif isinstance(rec, str) and rec.strip():
                    out.append({"name": rec.strip(), "areas": [], "notes": ""})
    except Exception:
        out = []
    return out


def _spina_crc_split_area(_area):
    try:
        if 'split_area_main_sub' in globals():
            return split_area_main_sub(_area)
    except Exception:
        pass
    a = str(_area or "").strip()
    for sep in [" | ", " / ", " - ", " > ", " : ", " — ", " – ", "|", "/", ">", ":"]:
        if sep in a:
            left, right = a.split(sep, 1)
            if left.strip() and right.strip():
                return left.strip(), right.strip()
    return a, ""


def _spina_crc_route_area_matches(route_area, client_area):
    """Match route area to client area, including MAIN-only collector routes covering subareas."""
    ra = str(route_area or "").strip()
    ca = str(client_area or "").strip()
    if not ra or not ca:
        return False
    nr = _spina_crc_norm_text(ra)
    nc = _spina_crc_norm_text(ca)
    if nr == nc:
        return True
    try:
        r_main, r_sub = _spina_crc_split_area(ra)
        c_main, c_sub = _spina_crc_split_area(ca)
        r_main_n = _spina_crc_norm_text(r_main)
        r_sub_n = _spina_crc_norm_text(r_sub)
        c_main_n = _spina_crc_norm_text(c_main)
        c_sub_n = _spina_crc_norm_text(c_sub)
        if r_main_n and r_main_n == c_main_n:
            # MAIN-only collector assignment covers all subareas under the same main area.
            if not r_sub_n:
                return True
            return bool(c_sub_n and r_sub_n == c_sub_n)
    except Exception:
        pass
    return False


def _spina_crc_collector_for_area(collectors, client_area):
    try:
        for col in (collectors or []):
            for ra in (col.get("areas") or []):
                if _spina_crc_route_area_matches(ra, client_area):
                    return col.get("name") or "Unassigned"
    except Exception:
        pass
    return "Unassigned"


def _spina_crc_key(uid, name, lt):
    uid = str(uid or "").strip()
    if uid:
        return ("UID", uid)
    return ("NAME", _spina_crc_norm_text(name), _spina_crc_norm_lt(lt))


def _spina_crc_fetch_close_rows(app, ds, collectors):
    """Build route rows with amount paid on the close date."""
    conn = getattr(getattr(app, "db", None), "conn", None)
    if conn is None:
        return []
    cur = conn.cursor()

    # Fetch active clients with a tolerant fallback for older schemas.
    try:
        cols = [r[1] for r in cur.execute("PRAGMA table_info(clients)").fetchall()]
    except Exception:
        cols = []
    wanted = ["client_uid", "name", "loan_type", "area", "payment_term", "payment_amount", "payment_mode"]
    select_cols = []
    for c in wanted:
        select_cols.append(c if c in cols else f"'' AS {c}")
    where = ""
    if "is_archived" in cols:
        where = "WHERE COALESCE(is_archived,0)=0"
    try:
        clients = cur.execute(
            "SELECT " + ", ".join(select_cols) + f" FROM clients {where} ORDER BY area COLLATE NOCASE, name COLLATE NOCASE"
        ).fetchall()
    except Exception:
        clients = []

    # Fetch all payments/entries for the closed day.
    try:
        txs = cur.execute(
            """
            SELECT client_uid, name, IFNULL(loan_type,'Regular') AS loan_type,
                   COALESCE(payment,0) AS payment, description
              FROM transactions
             WHERE date(date)=date(?)
             ORDER BY name COLLATE NOCASE, loan_type, id
            """,
            (ds,),
        ).fetchall()
    except Exception:
        txs = []

    paid_by_uid = {}
    paid_by_name = {}
    desc_by_key = {}
    tx_seen_keys = set()

    def _add_pay(store, key, pay, desc):
        try:
            store[key] = round(float(store.get(key, 0.0) or 0.0) + float(pay or 0.0), 2)
        except Exception:
            store[key] = float(pay or 0.0) if pay else 0.0
        d = _spina_crc_clean_reason(desc)
        if d:
            cur_txt = desc_by_key.get(key, "")
            if d not in cur_txt:
                desc_by_key[key] = (cur_txt + "; " + d).strip("; ").strip()

    for r in txs or []:
        try:
            d = dict(r)
        except Exception:
            d = {}
        uid = str(d.get("client_uid") or "").strip()
        nm = str(d.get("name") or "").strip()
        lt = _spina_crc_norm_lt(d.get("loan_type") or "Regular")
        pay = d.get("payment") or 0.0
        desc = d.get("description") or ""
        if uid:
            key = ("UID", uid)
            _add_pay(paid_by_uid, key, pay, desc)
            tx_seen_keys.add(key)
        key2 = ("NAME", _spina_crc_norm_text(nm), lt)
        _add_pay(paid_by_name, key2, pay, desc)
        tx_seen_keys.add(key2)

    out = []
    matched_tx_keys = set()
    for r in clients or []:
        try:
            d = dict(r)
        except Exception:
            d = {}
        nm = str(d.get("name") or "").strip()
        if not nm:
            continue
        lt = _spina_crc_norm_lt(d.get("loan_type") or "Regular")
        area = str(d.get("area") or "").strip()
        uid = str(d.get("client_uid") or "").strip()
        k_uid = ("UID", uid) if uid else None
        k_name = ("NAME", _spina_crc_norm_text(nm), lt)
        paid = 0.0
        reason = ""
        if k_uid and k_uid in paid_by_uid:
            paid = paid_by_uid.get(k_uid, 0.0)
            reason = desc_by_key.get(k_uid, "")
            matched_tx_keys.add(k_uid)
        elif k_name in paid_by_name:
            paid = paid_by_name.get(k_name, 0.0)
            reason = desc_by_key.get(k_name, "")
            matched_tx_keys.add(k_name)
        collector = _spina_crc_collector_for_area(collectors, area)
        term = str(d.get("payment_term") or "").strip()
        mode = str(d.get("payment_mode") or "").strip()
        try:
            sched_amt = float(d.get("payment_amount") or 0.0)
        except Exception:
            sched_amt = 0.0
        detail = ""
        try:
            parts = []
            if term:
                parts.append(term)
            if sched_amt:
                parts.append(_spina_crc_fmt_money(sched_amt))
            if mode:
                parts.append(mode)
            detail = " / ".join(parts)
        except Exception:
            detail = ""
        out.append({
            "collector": collector,
            "area": area or "-",
            "name": nm,
            "loan_type": lt,
            "paid": round(float(paid or 0.0), 2),
            "reason": reason,
            "detail": detail,
        })

    # Include payment rows that are not matched to active clients, so the close copy still ties to the day total.
    for r in txs or []:
        try:
            d = dict(r)
        except Exception:
            d = {}
        uid = str(d.get("client_uid") or "").strip()
        nm = str(d.get("name") or "").strip()
        lt = _spina_crc_norm_lt(d.get("loan_type") or "Regular")
        k = ("UID", uid) if uid else ("NAME", _spina_crc_norm_text(nm), lt)
        k2 = ("NAME", _spina_crc_norm_text(nm), lt)
        if (k in matched_tx_keys) or (k2 in matched_tx_keys):
            continue
        # Avoid duplicate unmatched rows when both UID and NAME keys are in tx_seen_keys.
        matched_tx_keys.add(k)
        if k2:
            matched_tx_keys.add(k2)
        try:
            pay = float(d.get("payment") or 0.0)
        except Exception:
            pay = 0.0
        if abs(pay) < 0.005:
            continue
        out.append({
            "collector": "Unassigned",
            "area": "-",
            "name": nm or "Unknown payment row",
            "loan_type": lt,
            "paid": round(pay, 2),
            "reason": _spina_crc_clean_reason(d.get("description") or ""),
            "detail": "payment row not matched to active client",
        })

    try:
        out.sort(key=lambda x: (str(x.get("collector") or "").lower(), str(x.get("area") or "").lower(), str(x.get("name") or "").lower(), str(x.get("loan_type") or "")))
    except Exception:
        pass
    return out


def _spina_crc_wrap(c, text, width, font="Helvetica", size=8.0):
    try:
        words = str(text or "").split()
    except Exception:
        words = []
    if not words:
        return [""]
    lines = []
    cur = ""
    for w in words:
        test = (cur + " " + w).strip()
        try:
            ok = c.stringWidth(test, font, size) <= width
        except Exception:
            ok = len(test) * size * 0.5 <= width
        if ok or not cur:
            cur = test
        else:
            lines.append(cur)
            cur = w
    if cur:
        lines.append(cur)
    return lines or [""]


def _spina_crc_copy_existing_route_pdfs(ds, out_dir):
    copied = []
    try:
        import glob as _glob
        import shutil as _shutil
        roots = []
        for r in [globals().get("PDF_DIR"), os.path.join(APP_DIR, "Client_Statements") if 'APP_DIR' in globals() else None]:
            if r and str(r) not in roots:
                roots.append(str(r))
        try:
            rr = data_path("reports")
            if rr not in roots:
                roots.append(rr)
        except Exception:
            pass
        for root in roots:
            if not root or not os.path.isdir(root):
                continue
            for pat in (f"*CollectorRoute*{ds}*.pdf", f"*FullDailyLedger*{ds}*.pdf"):
                for src in _glob.glob(os.path.join(root, pat)):
                    try:
                        if os.path.abspath(os.path.dirname(src)) == os.path.abspath(out_dir):
                            continue
                        base = os.path.basename(src)
                        dst = os.path.join(out_dir, "OriginalCopy_" + base)
                        if not os.path.exists(dst):
                            _shutil.copy2(src, dst)
                        copied.append(dst)
                    except Exception:
                        pass
    except Exception:
        pass
    return copied


def _spina_save_closed_collector_route_copy(self, date_s, rec=None, collector_rows=None, open_after=False):
    """Save an audit copy of the Collector Route after Daily Close.

    The PDF contains the closed total/actual cash for the day and the amount paid by each
    client on that date. It is separate from Generate Report and from editable Data Bank rows.
    """
    import os as _os
    from datetime import datetime as _dt
    try:
        from reportlab.pdfgen import canvas as _canvas
        from reportlab.lib.pagesizes import A4, landscape as _landscape
        from reportlab.lib import colors as _colors
    except Exception as e:
        raise RuntimeError("ReportLab is required to save the closed collector route PDF.") from e

    ds = str(date_s or "").strip()[:10]
    try:
        _dt.strptime(ds, "%Y-%m-%d")
    except Exception:
        raise ValueError("Use date format YYYY-MM-DD.")

    if rec is None:
        try:
            rec = self.db.get_databank_day_close(ds) if hasattr(self, "db") else None
        except Exception:
            rec = None
    if not rec:
        raise ValueError("No Daily Close record exists yet for that date.")

    def _rec_get(k, default=None):
        try:
            return rec.get(k, default)
        except Exception:
            try:
                return dict(rec).get(k, default)
            except Exception:
                return default

    try:
        expected = round(float(_rec_get("expected_amount", 0.0) or 0.0), 2)
    except Exception:
        expected = 0.0
    try:
        actual = round(float(_rec_get("actual_cash", 0.0) or 0.0), 2)
    except Exception:
        actual = 0.0
    try:
        variance = round(float(_rec_get("variance", actual - expected) or 0.0), 2)
    except Exception:
        variance = round(actual - expected, 2)
    if abs(variance) < 0.005:
        variance = 0.0
    try:
        reg_total = round(float(getattr(self, "db").get_databank_daily_total(ds, loan_type="Regular") or 0.0), 2)
    except Exception:
        reg_total = 0.0
    try:
        x7_total = round(float(getattr(self, "db").get_databank_daily_total(ds, loan_type="7x7") or 0.0), 2)
    except Exception:
        x7_total = 0.0

    collectors = _spina_crc_load_collectors()
    rows = _spina_crc_fetch_close_rows(self, ds, collectors)

    # Use saved collector split rows from the close record when available.
    close_collectors = []
    if collector_rows is not None:
        try:
            close_collectors = [dict(r) for r in (collector_rows or [])]
        except Exception:
            close_collectors = []
    if not close_collectors:
        try:
            close_collectors = list(self.db.list_databank_day_collectors(ds) or [])
        except Exception:
            close_collectors = []
    close_by_name = {}
    for r in close_collectors or []:
        try:
            nm = str((r or {}).get("collector_name") or "").strip()
            if nm:
                close_by_name[nm.lower()] = dict(r)
        except Exception:
            pass

    base_dir = ""
    try:
        base_dir = data_path("Closed_Collector_Routes", ds)
    except Exception:
        base_dir = _os.path.join(DATA_DIR if 'DATA_DIR' in globals() else _os.getcwd(), "Closed_Collector_Routes", ds)
    _os.makedirs(base_dir, exist_ok=True)
    stamp = _dt.now().strftime("%H%M%S")
    paid_tag = _safe_filename_component(_spina_crc_fmt_money(actual).replace(",", ""), fallback="0") if '_safe_filename_component' in globals() else str(int(actual or 0))
    out_path = _os.path.join(base_dir, f"ClosedCollectorRoute_{ds}_Paid_{paid_tag}_{stamp}.pdf")

    # Also copy any previously printed collector-route PDFs for the same date into the close folder.
    copied_route_pdfs = _spina_crc_copy_existing_route_pdfs(ds, base_dir)

    page_w, page_h = _landscape(A4)
    c = _canvas.Canvas(out_path, pagesize=(page_w, page_h))
    margin = 24
    y = page_h - margin
    line_h = 10.5

    col_no = 18
    col_area = 82
    col_name = 180
    col_type = 38
    col_paid = 70
    col_reason = page_w - (margin * 2) - (col_no + col_area + col_name + col_type + col_paid)

    def _new_page():
        nonlocal y
        c.showPage()
        y = page_h - margin
        _draw_header(small=True)

    def _ensure(h):
        if y - h < margin + 22:
            _new_page()

    def _draw_header(small=False):
        nonlocal y
        c.setFillColor(_colors.black)
        c.setFont("Helvetica-Bold", 13 if not small else 11)
        c.drawString(margin, y, f"CLOSED COLLECTOR ROUTE COPY - {ds}")
        c.setFont("Helvetica", 8.5)
        c.drawRightString(page_w - margin, y, "Saved after Daily Close")
        y -= 14
        if not small:
            c.setFont("Helvetica", 9)
            summary = (
                f"Amount Paid Today: { _spina_crc_fmt_money(actual) }    "
                f"Expected: { _spina_crc_fmt_money(expected) }    "
                f"Variance: { _spina_crc_fmt_money(variance) }    "
                f"Regular: { _spina_crc_fmt_money(reg_total) }    7x7: { _spina_crc_fmt_money(x7_total) }"
            )
            c.drawString(margin, y, summary)
            y -= 12
            closed_by = str(_rec_get("closed_by", "") or "").strip()
            closed_at = str(_rec_get("closed_at", "") or "").strip()
            wf = str(_rec_get("variance_workflow_status", "") or "").strip()
            c.drawString(margin, y, f"Closed by: {closed_by or '-'}    Closed at: {closed_at or '-'}    Workflow: {wf or '-'}")
            y -= 14
            if copied_route_pdfs:
                c.setFillColor(_colors.HexColor("#555555"))
                c.drawString(margin, y, f"Existing printed route PDF copy/copies saved in the same folder: {len(copied_route_pdfs)}")
                c.setFillColor(_colors.black)
                y -= 12
        c.setStrokeColor(_colors.HexColor("#999999"))
        c.line(margin, y, page_w - margin, y)
        y -= 10

    def _draw_table_header():
        nonlocal y
        _ensure(18)
        c.saveState()
        c.setFillColor(_colors.HexColor("#F2F2F2"))
        c.rect(margin, y - 13, page_w - (margin * 2), 15, stroke=0, fill=1)
        c.restoreState()
        c.setFont("Helvetica-Bold", 8)
        x = margin + 2
        for title, w in [("#", col_no), ("Area", col_area), ("Client", col_name), ("Type", col_type), ("Paid", col_paid), ("Reason / detail", col_reason)]:
            if title == "Paid":
                c.drawRightString(x + w - 3, y - 8, title)
            else:
                c.drawString(x, y - 8, title)
            x += w
        y -= 17

    _draw_header(small=False)

    if not rows:
        c.setFont("Helvetica", 10)
        c.drawString(margin, y, "No route/payment rows found for this date.")
        y -= 16
    else:
        # Keep collector order from collectors.json, then append any extra/unassigned groups.
        order = [str(c0.get("name") or "").strip() for c0 in collectors if str(c0.get("name") or "").strip()]
        groups = {}
        for r in rows:
            groups.setdefault(str(r.get("collector") or "Unassigned"), []).append(r)
        for g in list(groups.keys()):
            if g not in order:
                order.append(g)

        for collector in order:
            gr = groups.get(collector) or []
            if not gr and collector.lower() not in close_by_name:
                continue
            sum_paid = round(sum(float(r.get("paid") or 0.0) for r in gr), 2)
            close_rec = close_by_name.get(str(collector).lower(), {})
            try:
                close_actual = round(float((close_rec or {}).get("actual_cash") or 0.0), 2)
            except Exception:
                close_actual = 0.0
            try:
                close_expected = round(float((close_rec or {}).get("expected_amount") or 0.0), 2)
            except Exception:
                close_expected = 0.0
            _ensure(34)
            c.setFillColor(_colors.HexColor("#EAF2F8"))
            c.rect(margin, y - 16, page_w - (margin * 2), 18, stroke=0, fill=1)
            c.setFillColor(_colors.black)
            c.setFont("Helvetica-Bold", 9.5)
            title = f"Collector: {collector}"
            c.drawString(margin + 4, y - 10, title)
            c.setFont("Helvetica", 8.5)
            if close_rec:
                right = f"Closed actual: {_spina_crc_fmt_money(close_actual)}   Expected: {_spina_crc_fmt_money(close_expected)}   Route rows paid: {_spina_crc_fmt_money(sum_paid)}"
            else:
                right = f"Route rows paid: {_spina_crc_fmt_money(sum_paid)}"
            c.drawRightString(page_w - margin - 4, y - 10, right)
            y -= 24
            _draw_table_header()
            idx = 1
            for r in gr:
                area = str(r.get("area") or "-")
                nm = str(r.get("name") or "")
                lt = _spina_crc_norm_lt(r.get("loan_type") or "Regular")
                paid = _spina_crc_fmt_money(r.get("paid") or 0.0, blank_zero=True)
                reason = str(r.get("reason") or r.get("detail") or "")
                if r.get("detail") and reason:
                    if str(r.get("detail")) not in reason:
                        reason = (reason + " | " + str(r.get("detail"))).strip(" |")
                elif r.get("detail"):
                    reason = str(r.get("detail") or "")
                name_lines = _spina_crc_wrap(c, nm, col_name - 4, "Helvetica", 8.2)
                reason_lines = _spina_crc_wrap(c, reason, col_reason - 4, "Helvetica", 7.4)
                row_lines = max(1, len(name_lines), len(reason_lines))
                h = max(14, 8 + (row_lines * line_h))
                _ensure(h + 2)
                if idx % 2 == 0:
                    c.saveState()
                    c.setFillColor(_colors.HexColor("#FBFBFB"))
                    c.rect(margin, y - h + 2, page_w - (margin * 2), h, stroke=0, fill=1)
                    c.restoreState()
                c.setStrokeColor(_colors.HexColor("#DDDDDD"))
                c.line(margin, y - h + 2, page_w - margin, y - h + 2)
                c.setFillColor(_colors.black)
                c.setFont("Helvetica", 8)
                x = margin + 2
                c.drawString(x, y - 8, str(idx)); x += col_no
                area_lines = _spina_crc_wrap(c, area, col_area - 4, "Helvetica", 7.6)
                for i, ln in enumerate(area_lines[:row_lines]):
                    c.drawString(x, y - 8 - (i * line_h), ln)
                x += col_area
                c.setFont("Helvetica-Bold", 8.2)
                for i, ln in enumerate(name_lines):
                    c.drawString(x, y - 8 - (i * line_h), ln)
                x += col_name
                c.setFont("Helvetica", 8)
                c.drawString(x, y - 8, "7x7" if lt == "7x7" else "REG")
                x += col_type
                c.setFont("Helvetica-Bold", 8)
                c.drawRightString(x + col_paid - 4, y - 8, paid)
                x += col_paid
                c.setFont("Helvetica", 7.4)
                for i, ln in enumerate(reason_lines[:max(1, row_lines)]):
                    c.drawString(x, y - 8 - (i * line_h), ln)
                y -= h
                idx += 1
            y -= 6

    _ensure(24)
    c.setFont("Helvetica-Oblique", 7.5)
    c.setFillColor(_colors.HexColor("#666666"))
    c.drawString(margin, margin - 2 + 10, "This PDF was saved automatically when the Data Bank day was closed. Amounts are from that close date's payment records.")
    c.drawRightString(page_w - margin, margin - 2 + 10, f"Saved: {_dt.now().strftime('%Y-%m-%d %H:%M:%S')}")
    c.save()

    try:
        self._last_closed_collector_route_copy_path = out_path
    except Exception:
        pass
    if open_after:
        try:
            _open_path(out_path)
        except Exception:
            pass
    return out_path


try:
    setattr(App, 'save_closed_collector_route_copy', _spina_save_closed_collector_route_copy)
except Exception as __spina_exc:
    try:
        _log_suppressed_once('closed_route_copy_patch_failed', 'closed collector route copy patch failed', __spina_exc)
    except Exception:
        pass
