# --- BEGIN: Closed route copy uses SAME Collector Route PDF format ---
def _spina_crc_build_paid_cache_for_date(app, ds):
    """Return {(lower_name, lower_loan_type): paid_amount} for the closed date."""
    out = {}
    try:
        conn = getattr(getattr(app, "db", None), "conn", None)
        if conn is None:
            return out
        rows = conn.execute(
            """
            SELECT name,
                   CASE WHEN LOWER(REPLACE(REPLACE(IFNULL(loan_type,'Regular'),' ',''),'×','x')) LIKE '%7x7%' THEN '7x7' ELSE 'regular' END AS lt,
                   COALESCE(SUM(COALESCE(payment,0)),0) AS paid
              FROM transactions
             WHERE date(date)=date(?)
             GROUP BY UPPER(TRIM(name)), lt
            """,
            (str(ds or '')[:10],),
        ).fetchall()
        for r in rows or []:
            try:
                nm = str(r['name'] if hasattr(r, 'keys') else r[0] or '').strip().lower()
                lt = str(r['lt'] if hasattr(r, 'keys') else r[1] or 'regular').strip().lower()
                paid = float(r['paid'] if hasattr(r, 'keys') else r[2] or 0.0)
                if nm:
                    out[(nm, lt)] = round(paid, 2)
            except Exception:
                continue
    except Exception as __spina_exc:
        try:
            _log_suppressed_once('closed_route_paid_cache_failed', 'closed route paid cache failed', __spina_exc)
        except Exception:
            pass
    return out


def _spina_crc_active_filtered_areas_for_collector(app, areas):
    """Match the Collector Route screen filtering so blank/archived-only areas are skipped."""
    try:
        def _route_norm(_s):
            return " ".join(str(_s or '').split()).strip().lower()
        cur = app.db.conn.cursor()
        active_rows = cur.execute(
            "SELECT DISTINCT TRIM(area) AS a FROM clients WHERE IFNULL(TRIM(area),'')<>'' AND COALESCE(is_archived,0)=0 ORDER BY a COLLATE NOCASE"
        ).fetchall()
        active_areas = []
        for r in active_rows or []:
            try:
                a = r['a'] if hasattr(r, 'keys') else r[0]
            except Exception:
                a = ''
            a = str(a or '').strip()
            if a:
                active_areas.append(a)
        active_full, active_main, active_pairs = set(), set(), set()
        for a in active_areas:
            full = _route_norm(a)
            if full:
                active_full.add(full)
            try:
                ma, su = split_area_main_sub(a)
            except Exception:
                ma, su = a, ''
            mn, sn = _route_norm(ma), _route_norm(su)
            if mn:
                active_main.add(mn)
            if mn and sn:
                active_pairs.add((mn, sn))
        filtered, seen = [], set()
        for ra in areas or []:
            ra = str(ra or '').strip()
            if not ra:
                continue
            try:
                rma, rsu = split_area_main_sub(ra)
            except Exception:
                rma, rsu = ra, ''
            rn, rmn, rsn = _route_norm(ra), _route_norm(rma), _route_norm(rsu)
            ok = False
            if rsn:
                ok = ((rmn, rsn) in active_pairs) or (rn in active_full)
            else:
                ok = (rmn in active_main) or (rn in active_full)
            if ok and ra not in seen:
                filtered.append(ra)
                seen.add(ra)
        return filtered
    except Exception:
        return [str(a).strip() for a in (areas or []) if str(a).strip()]


def _spina_save_closed_collector_route_copy_same_format(self, date_s, rec=None, collector_rows=None, open_after=False):
    """Save final closed Collector Route copy using the SAME Collector Route PDF layout.

    Difference from normal print: the payment columns are filled with the actual amount
    paid on the closed date, and the PDF is saved silently under data/Closed_Collector_Routes.
    """
    import os as _os
    import shutil as _shutil
    from datetime import datetime as _dt

    ds = str(date_s or '').strip()[:10]
    try:
        _dt.strptime(ds, '%Y-%m-%d')
    except Exception:
        raise ValueError('Use date format YYYY-MM-DD.')

    if rec is None:
        try:
            rec = self.db.get_databank_day_close(ds) if hasattr(self, 'db') else None
        except Exception:
            rec = None
    if not rec:
        raise ValueError('No Daily Close record exists yet for that date.')

    try:
        base_dir = data_path('Closed_Collector_Routes', ds)
    except Exception:
        base_dir = _os.path.join(DATA_DIR if 'DATA_DIR' in globals() else _os.getcwd(), 'Closed_Collector_Routes', ds)
    _os.makedirs(base_dir, exist_ok=True)

    collectors = _spina_crc_load_collectors() if '_spina_crc_load_collectors' in globals() else []
    paid_cache = _spina_crc_build_paid_cache_for_date(self, ds)
    saved_paths = []
    old_pdf_dir = globals().get('PDF_DIR', None)

    def _safe_tag(_v, fallback='Collector'):
        try:
            return _safe_filename_component(_v, fallback=fallback)
        except Exception:
            return str(_v or fallback).replace(' ', '_')

    def _generate_one(collector_name, areas):
        collector_name = str(collector_name or 'All Collectors').strip() or 'All Collectors'
        areas = [str(a).strip() for a in (areas or []) if str(a).strip()]
        if not areas:
            return None
        # Use the exact Collector Route generator, but force date/output and suppress dialogs/opening.
        old_attrs = {}
        for attr in (
            '_ledger_forced_areas', '_ledger_forced_collector_name', '_route_payment_two_cols',
            '_ledger_silent_route_copy', '_ledger_forced_date', '_ledger_forced_output_dir',
            '_ledger_forced_paper_label', '_ledger_forced_orientation', '_ledger_closed_copy_show_paid',
            '_ledger_closed_paid_cache', '_last_printed_daily_ledger_path'
        ):
            try:
                old_attrs[attr] = (True, getattr(self, attr))
            except Exception:
                old_attrs[attr] = (False, None)
        try:
            self._ledger_forced_areas = areas
            self._ledger_forced_collector_name = collector_name
            self._route_payment_two_cols = True
            self._ledger_silent_route_copy = True
            self._ledger_forced_date = ds
            self._ledger_forced_output_dir = base_dir
            self._ledger_forced_paper_label = 'Folio (8 x 13 in)'
            self._ledger_forced_orientation = 'Portrait'
            self._ledger_closed_copy_show_paid = True
            self._ledger_closed_paid_cache = paid_cache
            self._last_printed_daily_ledger_path = ''
            try:
                globals()['PDF_DIR'] = base_dir
            except Exception:
                pass
            self.print_full_daily_ledger()
            p = str(getattr(self, '_last_printed_daily_ledger_path', '') or '')
            if p and _os.path.exists(p):
                stamp = _dt.now().strftime('%H%M%S')
                final_name = f"ClosedCollectorRoute_{_safe_tag(collector_name)}_{ds}_{stamp}.pdf"
                final_path = _os.path.join(base_dir, final_name)
                try:
                    if _os.path.abspath(p) != _os.path.abspath(final_path):
                        if _os.path.exists(final_path):
                            _os.remove(final_path)
                        _shutil.move(p, final_path)
                    p = final_path
                except Exception:
                    pass
                return p
            return None
        finally:
            for attr, (exists, value) in old_attrs.items():
                try:
                    if exists:
                        setattr(self, attr, value)
                    else:
                        if hasattr(self, attr):
                            delattr(self, attr)
                except Exception:
                    pass

    if collectors:
        for col in collectors:
            try:
                cname = str((col or {}).get('name') or '').strip()
                areas = list((col or {}).get('areas') or [])
                areas = _spina_crc_active_filtered_areas_for_collector(self, areas)
                if not cname or not areas:
                    continue
                p = _generate_one(cname, areas)
                if p:
                    saved_paths.append(p)
            except Exception as __spina_exc:
                try:
                    _log_suppressed_once('closed_route_generate_one_failed', 'closed route same-format collector copy failed', __spina_exc)
                except Exception:
                    pass
    else:
        # Fallback: use all active areas in the same ledger layout.
        try:
            cur = self.db.conn.cursor()
            rows = cur.execute("SELECT DISTINCT TRIM(area) AS a FROM clients WHERE IFNULL(TRIM(area),'')<>'' AND COALESCE(is_archived,0)=0 ORDER BY a COLLATE NOCASE").fetchall()
            all_areas = [str((r['a'] if hasattr(r, 'keys') else r[0]) or '').strip() for r in rows]
        except Exception:
            all_areas = []
        p = _generate_one('All Collectors', all_areas)
        if p:
            saved_paths.append(p)

    try:
        if old_pdf_dir:
            globals()['PDF_DIR'] = old_pdf_dir
    except Exception:
        pass

    if not saved_paths:
        raise RuntimeError('No collector route PDF was generated. Check collectors.json and active client areas.')

    # Small text manifest only; the PDFs remain the same Collector Route format.
    try:
        manifest = _os.path.join(base_dir, f'ClosedCollectorRoute_{ds}_MANIFEST.txt')
        def _rec_get(k, default=''):
            try:
                return rec.get(k, default)
            except Exception:
                try:
                    return dict(rec).get(k, default)
                except Exception:
                    return default
        with open(manifest, 'w', encoding='utf-8') as f:
            f.write(f'Closed Collector Route copies for {ds}\n')
            f.write(f'Expected: {_rec_get("expected_amount", "")}\n')
            f.write(f'Actual / Amount Paid Today: {_rec_get("actual_cash", "")}\n')
            f.write(f'Variance: {_rec_get("variance", "")}\n')
            f.write('\nFiles:\n')
            for p in saved_paths:
                f.write('- ' + _os.path.basename(p) + '\n')
    except Exception:
        pass

    try:
        self._last_closed_collector_route_copy_path = saved_paths[0] if len(saved_paths) == 1 else base_dir
    except Exception:
        pass
    if open_after:
        try:
            _open_path(base_dir if len(saved_paths) != 1 else saved_paths[0])
        except Exception:
            pass
    return base_dir if len(saved_paths) != 1 else saved_paths[0]

try:
    App.save_closed_collector_route_copy = _spina_save_closed_collector_route_copy_same_format
except Exception as __spina_exc:
    try:
        _log_suppressed_once('closed_route_same_format_bind_failed', 'closed route same-format bind failed', __spina_exc)
    except Exception:
        pass
# --- END: Closed route copy uses SAME Collector Route PDF format ---



# --- BEGIN: PostgreSQL TEST renew direct-write fix ---
# Renew is write-heavy and touches clients + renewals + history. The old SQLite
# code can fail under the compatibility layer because PostgreSQL uses sequences
# and stricter SQL rules. This override uses psycopg directly when running in
# PostgreSQL TEST MODE, while leaving the original SQLite method untouched.
try:
    _SPINA_ORIG_LOANDB_RENEW_CLIENT = LoanDB.renew_client
except Exception:
    _SPINA_ORIG_LOANDB_RENEW_CLIENT = None


def _spina_pg__reset_id_sequence(cur, table_name):
    """Move a PostgreSQL BIGSERIAL/SERIAL sequence after the current MAX(id)."""
    try:
        t = str(table_name or '').strip()
        if t not in {'clients', 'transactions', 'transaction_history', 'renewals', 'client_history', 'databank_day_close', 'databank_day_close_history', 'databank_day_collector_close'}:
            return
        cur.execute("SELECT pg_get_serial_sequence(%s, 'id')", (f'public.{t}',))
        row = cur.fetchone()
        seq = row[0] if row else None
        if not seq:
            return
        cur.execute(f"SELECT COALESCE(MAX(id), 0) FROM public.{t}")
        row = cur.fetchone()
        max_id = int(row[0] or 0) if row else 0
        if max_id > 0:
            cur.execute("SELECT setval(%s::regclass, %s, true)", (seq, max_id))
        else:
            cur.execute("SELECT setval(%s::regclass, 1, false)", (seq,))
    except Exception:
        # Never block the main renew path only because sequence repair failed.
        pass


def _spina_pg__table_has_column(cur, table_name, column_name):
    try:
        cur.execute(
            """
            SELECT 1
              FROM information_schema.columns
             WHERE table_schema='public'
               AND table_name=%s
               AND column_name=%s
             LIMIT 1
            """,
            (str(table_name or ''), str(column_name or ''))
        )
        return cur.fetchone() is not None
    except Exception:
        return False


def _spina_pg_renew_client_direct(self, name, released_cash, renew_date=None, new_principal=None, loan_type=None, interest_rate=None, note='', pay_start_offset_days=None):
    """PostgreSQL-safe renew/reloan implementation for the TEST build."""
    if not globals().get('SPINA_POSTGRESQL_TEST_MODE', False):
        if _SPINA_ORIG_LOANDB_RENEW_CLIENT:
            return _SPINA_ORIG_LOANDB_RENEW_CLIENT(self, name, released_cash, renew_date, new_principal, loan_type, interest_rate, note, pay_start_offset_days)
        return False

    pg = getattr(getattr(self, 'conn', None), '_pg', None)
    if pg is None:
        if _SPINA_ORIG_LOANDB_RENEW_CLIENT:
            return _SPINA_ORIG_LOANDB_RENEW_CLIENT(self, name, released_cash, renew_date, new_principal, loan_type, interest_rate, note, pay_start_offset_days)
        return False

    try:
        self._last_renew_error = ''
    except Exception:
        pass

    try:
        lt = self._effective_lt(loan_type)
    except Exception:
        lt = '7x7' if str(loan_type or '').lower().replace('×', 'x').replace(' ', '') == '7x7' else 'Regular'

    try:
        info = self.get_client_info(name, loan_type=lt) or {}
    except Exception:
        info = {}
    if not info:
        try:
            self._last_renew_error = 'Client not found in database for renew.'
        except Exception:
            pass
        return False

    uid = str((info.get('client_uid') or '')).strip()
    old_row = dict(info)

    # Renew date
    if not renew_date:
        rd = date.today().strftime('%Y-%m-%d')
    else:
        try:
            rd = datetime.strptime(str(renew_date)[:10], '%Y-%m-%d').strftime('%Y-%m-%d')
        except Exception:
            rd = date.today().strftime('%Y-%m-%d')

    # Start-of-payment offset for the NEW cycle.
    if pay_start_offset_days is None:
        try:
            psod = int(info.get('pay_start_offset_days') or 0)
        except Exception:
            psod = 0
    else:
        try:
            psod = int(pay_start_offset_days or 0)
        except Exception:
            psod = 0
    psod = 1 if psod >= 1 else 0
    try:
        payment_start = (datetime.strptime(rd, '%Y-%m-%d').date() + timedelta(days=psod)).strftime('%Y-%m-%d')
    except Exception:
        payment_start = rd

    # Cash and principal.
    try:
        rc = float(str(released_cash or 0).replace(',', ''))
    except Exception:
        rc = 0.0
    if new_principal is None or str(new_principal).strip() == '':
        new_principal = rc
    try:
        p = float(str(new_principal or 0).replace(',', ''))
    except Exception:
        p = 0.0

    # Interest.
    try:
        r = float(str(interest_rate).replace(',', '')) if interest_rate is not None else float(info.get('interest_rate') or 0.20)
        if r > 1.0:
            r = r / 100.0
    except Exception:
        r = 0.20
    if str(lt).lower().replace('×', 'x').replace(' ', '') == '7x7':
        r = 0.0

    intr = round(float(p) * float(r), 2)
    total = round(float(p) + float(intr), 2)
    due_days = 49 if str(lt).lower().replace('×', 'x').replace(' ', '') == '7x7' else 120
    try:
        due = (datetime.strptime(rd, '%Y-%m-%d').date() + timedelta(days=due_days)).strftime('%Y-%m-%d')
    except Exception:
        due = rd

    try:
        with pg.cursor() as cur:
            # Make sure the columns used by the newer app exist in the PostgreSQL test database.
            try:
                cur.execute("ALTER TABLE public.clients ADD COLUMN IF NOT EXISTS payment_start_date TEXT")
            except Exception:
                try:
                    pg.rollback()
                except Exception:
                    pass
                cur = pg.cursor()

            _spina_pg__reset_id_sequence(cur, 'renewals')
            _spina_pg__reset_id_sequence(cur, 'client_history')

            has_payment_start = _spina_pg__table_has_column(cur, 'clients', 'payment_start_date')

            if uid:
                if has_payment_start:
                    cur.execute(
                        """
                        UPDATE public.clients
                           SET principal=%s,
                               interest_rate=%s,
                               interest_amount=%s,
                               total_to_pay=%s,
                               date_released=%s,
                               due_date=%s,
                               new_until=NULL,
                               last_released_cash=%s,
                               renew_count=COALESCE(renew_count,0)+1,
                               pay_start_offset_days=%s,
                               payment_start_date=%s
                         WHERE client_uid=%s
                        """,
                        (p, r, intr, total, rd, due, rc, psod, payment_start, uid)
                    )
                else:
                    cur.execute(
                        """
                        UPDATE public.clients
                           SET principal=%s,
                               interest_rate=%s,
                               interest_amount=%s,
                               total_to_pay=%s,
                               date_released=%s,
                               due_date=%s,
                               new_until=NULL,
                               last_released_cash=%s,
                               renew_count=COALESCE(renew_count,0)+1,
                               pay_start_offset_days=%s
                         WHERE client_uid=%s
                        """,
                        (p, r, intr, total, rd, due, rc, psod, uid)
                    )
            else:
                if has_payment_start:
                    cur.execute(
                        """
                        UPDATE public.clients
                           SET principal=%s,
                               interest_rate=%s,
                               interest_amount=%s,
                               total_to_pay=%s,
                               date_released=%s,
                               due_date=%s,
                               new_until=NULL,
                               last_released_cash=%s,
                               renew_count=COALESCE(renew_count,0)+1,
                               pay_start_offset_days=%s,
                               payment_start_date=%s
                         WHERE TRIM(name)=TRIM(%s) AND loan_type=%s
                        """,
                        (p, r, intr, total, rd, due, rc, psod, payment_start, name, lt)
                    )
                else:
                    cur.execute(
                        """
                        UPDATE public.clients
                           SET principal=%s,
                               interest_rate=%s,
                               interest_amount=%s,
                               total_to_pay=%s,
                               date_released=%s,
                               due_date=%s,
                               new_until=NULL,
                               last_released_cash=%s,
                               renew_count=COALESCE(renew_count,0)+1,
                               pay_start_offset_days=%s
                         WHERE TRIM(name)=TRIM(%s) AND loan_type=%s
                        """,
                        (p, r, intr, total, rd, due, rc, psod, name, lt)
                    )

            updated = int(cur.rowcount or 0)
            if updated <= 0:
                raise RuntimeError(f'No client row was updated. Name={name!r}, loan_type={lt!r}, client_uid={uid!r}')

            if uid:
                cur.execute(
                    """
                    INSERT INTO public.renewals
                        (client_uid, loan_type, renew_date, released_cash, principal_after, interest_rate, note, created_at)
                    VALUES
                        (%s, %s, %s, %s, %s, %s, %s, CURRENT_TIMESTAMP::text)
                    """,
                    (uid, lt, rd, rc, p, r, str(note or '').strip())
                )

        pg.commit()
    except Exception as e:
        try:
            pg.rollback()
        except Exception:
            pass
        msg = str(e)
        try:
            self._last_renew_error = msg
        except Exception:
            pass
        try:
            _log_exc('postgres direct renew_client', e)
        except Exception:
            pass
        return False

    try:
        new_row = self.get_client_info(name, loan_type=lt) or {}
        self._log_client_history((new_row.get('client_uid') or uid), 'RENEW', old_row=old_row, new_row=new_row, source='clients:renew:postgres', note=str(note or '').strip())
    except Exception:
        pass

    return True

try:
    if globals().get('SPINA_POSTGRESQL_TEST_MODE', False):
        LoanDB.renew_client = _spina_pg_renew_client_direct
except Exception as __spina_exc:
    try:
        _log_suppressed_once('pg_renew_direct_bind_failed', 'PostgreSQL direct renew bind failed', __spina_exc)
    except Exception:
        pass
# --- END: PostgreSQL TEST renew direct-write fix ---



# --- BEGIN: PostgreSQL TEST v7 Collector Route ADV UID/person_uid fallback ---
def _spina_route_adv_marker_for(db, name: str, day_yyyy_mm_dd: str, loan_type: str = "Regular"):
    """Collector Route ADV lookup with stronger PostgreSQL migration fallback.

    This version does not rely only on the printed route name. It finds the
    client_uid/person_uid from clients first, then checks every matching
    transaction name/uid for the selected loan type. This fixes migrated data
    where a linked 7x7 account name differs from the Regular display name.
    """
    try:
        import re as _re_v7
        day = str(day_yyyy_mm_dd or "")[:10].strip()
        raw_name = str(name or "").strip()
        if not day or not raw_name:
            return (False, "")

        def _norm_name_v7(v):
            s = str(v or "").strip()
            s = _re_v7.sub(r"\s*\((?:7x7|7×7|regular|reg)\)\s*$", "", s, flags=_re_v7.IGNORECASE).strip()
            s = _re_v7.sub(r"\s+", " ", s)
            return s

        def _lt_key_v7(v):
            z = str(v or "Regular").lower().replace(" ", "").replace("×", "x")
            return "7x7" if "7x7" in z else "regular"

        lt_key = _lt_key_v7(loan_type)
        display_name = _norm_name_v7(raw_name)
        names = set([display_name, raw_name])
        uids = set()
        person_uids = set()

        cur = db.conn.cursor()

        # 1) Resolve client rows by name + requested loan type.
        try:
            cur.execute(
                """
                SELECT client_uid, person_uid, name, loan_type
                  FROM clients
                 WHERE UPPER(TRIM(name)) = UPPER(TRIM(?))
                   AND (CASE WHEN LOWER(REPLACE(REPLACE(COALESCE(loan_type,'Regular'),' ',''),'×','x')) LIKE '%7x7%' THEN '7x7' ELSE 'regular' END) = ?
                """,
                (display_name, lt_key),
            )
            for r in (cur.fetchall() or []):
                try:
                    if r['client_uid']:
                        uids.add(str(r['client_uid']).strip())
                    if r['person_uid']:
                        person_uids.add(str(r['person_uid']).strip())
                    if r['name']:
                        names.add(_norm_name_v7(r['name']))
                except Exception:
                    pass
        except Exception:
            pass

        # 2) If helper exists, try it too because it may resolve client_uid better.
        try:
            if hasattr(db, 'get_client_uid'):
                _uid = str(db.get_client_uid(display_name, loan_type=("7x7" if lt_key == "7x7" else "Regular")) or "").strip()
                if _uid:
                    uids.add(_uid)
        except Exception:
            pass

        # 3) If a person_uid is known, include same-person account names/uids for the same requested loan type.
        try:
            for pu in list(person_uids):
                if not pu:
                    continue
                cur.execute(
                    """
                    SELECT client_uid, person_uid, name, loan_type
                      FROM clients
                     WHERE TRIM(COALESCE(person_uid,'')) = TRIM(?)
                    """,
                    (pu,),
                )
                for r in (cur.fetchall() or []):
                    try:
                        r_lt = _lt_key_v7(r['loan_type'])
                        if r_lt != lt_key:
                            continue
                        if r['client_uid']:
                            uids.add(str(r['client_uid']).strip())
                        if r['person_uid']:
                            person_uids.add(str(r['person_uid']).strip())
                        if r['name']:
                            names.add(_norm_name_v7(r['name']))
                    except Exception:
                        pass
        except Exception:
            pass

        # Clean sets.
        names = {n for n in names if str(n or '').strip()}
        uids = {u for u in uids if str(u or '').strip()}

        # 4) Build a broad-but-safe transaction lookup.
        clauses = []
        params = []
        if uids:
            clauses.append("client_uid IN (" + ",".join(["?"] * len(uids)) + ")")
            params.extend(sorted(uids))
        if names:
            clauses.append("UPPER(TRIM(name)) IN (" + ",".join(["UPPER(TRIM(?))"] * len(names)) + ")")
            params.extend(sorted(names))
        if not clauses:
            return (False, "")

        sql = """
            SELECT date, description, name, client_uid, loan_type
              FROM transactions
             WHERE description IS NOT NULL
               AND TRIM(description) <> ''
               AND UPPER(description) LIKE '%ADV%'
               AND (CASE WHEN LOWER(REPLACE(REPLACE(COALESCE(loan_type,'Regular'),' ',''),'×','x')) LIKE '%7x7%' THEN '7x7' ELSE 'regular' END) = ?
               AND (""" + " OR ".join(clauses) + ")"
        cur.execute(sql, tuple([lt_key] + params))
        rows = cur.fetchall() or []

        best_end = ""
        for r in rows:
            try:
                desc = r['description'] if hasattr(r, 'keys') else r[1]
            except Exception:
                desc = ""
            for s, e in (parse_advance_ranges(desc or "") or []):
                ss = str(s or "")[:10]
                ee = str(e or "")[:10]
                if not ss or not ee:
                    continue
                if ee < ss:
                    ss, ee = ee, ss
                if ss <= day <= ee:
                    if (not best_end) or ee > best_end:
                        best_end = ee

        # 5) Last fallback: ignore loan type, but only when exact client_uid/name matches.
        # This catches old ADV entries saved with blank/wrong loan_type after import.
        if not best_end:
            sql2 = """
                SELECT date, description, name, client_uid, loan_type
                  FROM transactions
                 WHERE description IS NOT NULL
                   AND TRIM(description) <> ''
                   AND UPPER(description) LIKE '%ADV%'
                   AND (""" + " OR ".join(clauses) + ")"
            cur.execute(sql2, tuple(params))
            for r in (cur.fetchall() or []):
                try:
                    desc = r['description'] if hasattr(r, 'keys') else r[1]
                except Exception:
                    desc = ""
                for s, e in (parse_advance_ranges(desc or "") or []):
                    ss = str(s or "")[:10]
                    ee = str(e or "")[:10]
                    if not ss or not ee:
                        continue
                    if ee < ss:
                        ss, ee = ee, ss
                    if ss <= day <= ee:
                        if (not best_end) or ee > best_end:
                            best_end = ee

        return (bool(best_end), best_end)
    except Exception as __spina_exc:
        try:
            _log_suppressed_once('route_adv_marker_lookup_failed_v7', 'collector route ADV lookup failed v7', __spina_exc)
        except Exception:
            pass
        return (False, "")
# --- END: PostgreSQL TEST v7 Collector Route ADV UID/person_uid fallback ---




