def _spina_v32_switch_account(self):
    old_user = getattr(self, "user_name", "") or ""
    old_display = _spina_v32_account_display_name(self, old_user) if old_user else ""

    try:
        u, r = self._prompt_login(default_user=(self.user_name or "admin"))
    except Exception as e:
        try:
            _log_exc("switch_account_login", e)
        except Exception:
            pass
        try:
            messagebox.showerror("Switch Account", "Failed to open the account sign-in window. See log for details.")
        except Exception:
            pass
        return

    if not u or not r:
        return

    self.user_name = u
    self.user_role = r

    try:
        self._save_last_user(self.user_name)
    except Exception:
        pass
    try:
        self._save_user_role(self.user_role)
    except Exception:
        pass

    try:
        self._refresh_user_header()
    except Exception:
        pass
    try:
        self._rebuild_side_nav()
    except Exception:
        pass

    try:
        self.apply_role_access()
    except Exception as e:
        try:
            _log_exc("switch_account_apply_role_access", e)
        except Exception:
            pass
        try:
            messagebox.showwarning("Switch Account", "The account was switched, but the UI permissions could not be fully refreshed. Please restart the app if something looks wrong.")
        except Exception:
            pass

    try:
        new_display = _spina_v32_account_display_name(self, self.user_name)
        self.status_var.set(f"Switched account: {old_display or old_user} → {new_display}")
    except Exception:
        pass


def _spina_v32_prompt_user_role(self, default: str = "Admin") -> str:
    # Fallback only. Do not show the old role selector anymore.
    d = str(default or "Admin").strip()
    return d if d in ("Admin", "Encoder", "Viewer", "System") else "Admin"


